"""Beta 0.45 content, applied on top of patch_039.   usage: python tools/content/patch_040.py"""
import sys as _sys, os as _os
_sys.path.insert(0, _os.path.dirname(_os.path.dirname(_os.path.abspath(__file__))))   # tools/ (its folders: _root)
import _root
import json
import patch_039 as P9

C, T, G, put_ui = P9.C, P9.T, P9.G, P9.put_ui

# XP: the ambers on the ground -25 % again; the bosses' amber halved again (killing one gave several levels in a row)
for m in C['monsters'].values(): m['xp'] = round(m['xp'] * 0.75, 4)
for b in C['bosses'].values(): b['xp'] = round(b['xp'] * 0.5, 2)

# no weapon pushes the monsters back any more: the knock-back becomes a short stun (they stay where they are,
# in the blow's reach) and the descriptions say so
STUN = {'baton': 0.25, 'god_rod': 0.25, 'bardiche': 0.25}
for w in C['weapons'] + C['uniqueWeapons']:
    if w['base'].pop('knock', None) is not None and w['id'] in STUN: w['base']['stun'] = max(w['base'].get('stun', 0), STUN[w['id']])
EVO = {   # weaponEvo[id][i]: the step's 'add' and its new description
    ('baton', 1): ({'stun': 0.35}, T('Étourdit les ennemis bien plus longtemps.', 'Stuns enemies for much longer.', 'Betäubt Gegner viel länger.', 'Aturde a los enemigos mucho más tiempo.', 'Stordisce i nemici molto più a lungo.', 'Verdooft vijanden veel langer.', 'Atordoa os inimigos durante muito mais tempo.'),
                   T('Assommoir', 'Knockout Blow', 'Betäubungshieb', 'Porrazo', 'Colpo Stordente', 'Verdovingsslag', 'Pancada')),
    ('god_rod', 2): ({'stun': 0.2}, T('+45 % de dégâts. Étourdit plus longtemps.', '+45% damage. Stuns for longer.', '+45 % Schaden. Betäubt länger.', '+45 % de daño. Aturde durante más tiempo.', '+45% di danni. Stordisce più a lungo.', '+45% schade. Verdooft langer.', '+45% de dano. Atordoa durante mais tempo.'), None),
    ('epee_qui_pete', 1): ({'stun': 0.3}, T('L\'odeur étourdit les monstres touchés (0,3 s).', 'The smell stuns the monsters it hits (0.3 s).', 'Der Gestank betäubt getroffene Monster (0,3 s).', 'El olor aturde a los monstruos golpeados (0,3 s).', 'L\'odore stordisce i mostri colpiti (0,3 s).', 'De geur verdooft de geraakte monsters (0,3 s).', 'O cheiro atordoa os monstros atingidos (0,3 s).'), None),
    ('marteau_dragoeuf', 2): ({'radius': 40, 'stun': 0.2}, T('Zone d\'impact plus grande. Étourdit plus longtemps.', 'Bigger impact area. Stuns for longer.', 'Größerer Wirkungsbereich. Betäubt länger.', 'Zona de impacto mayor. Aturde durante más tiempo.', 'Zona d\'impatto più grande. Stordisce più a lungo.', 'Groter inslaggebied. Verdooft langer.', 'Zona de impacto maior. Atordoa durante mais tempo.'), None),
    ('bardiche', 1): ({'stun': 0.4}, T('Étourdit bien plus longtemps.', 'Stuns for much longer.', 'Betäubt viel länger.', 'Aturde durante mucho más tiempo.', 'Stordisce molto più a lungo.', 'Verdooft veel langer.', 'Atordoa durante muito mais tempo.'), None),
}
for (wid, i), (add, desc, name) in EVO.items():
    e = C['weaponEvo'][wid][i]; e['add'] = add; e['desc'] = desc
    if name: e['name'] = name
for evs in C['weaponEvo'].values():
    for e in evs:
        if e.get('add'): e['add'].pop('knock', None)
for w in C['weapons']:
    if w['id'] == 'baton':
        w['desc'] = T('Un grand moulinet de bâton qui balaie les ennemis et les étourdit un instant.',
                      'A wide staff sweep that hits every enemy around and stuns them for a moment.',
                      'Ein weiter Stabschwung, der Gegner trifft und kurz betäubt.',
                      'Un amplio molinete de bastón que barre a los enemigos y los aturde un instante.',
                      'Un ampio mulinello di bastone che spazza i nemici e li stordisce per un attimo.',
                      'Een brede zwaai met de staf die vijanden raakt en even verdooft.',
                      'Um amplo giro de cajado que varre os inimigos e os atordoa por um instante.')
for w in C['uniqueWeapons']:
    if w['id'] == 'bardiche':
        w['desc'] = T('Une hache d\'arme à très longue portée qui étourdit les monstres touchés. La Milice frappe de loin, et vous aussi.',
                      'A very long reach poleaxe that stuns the monsters it hits. The Militia strikes from afar, and so do you.',
                      'Eine Hellebarde mit sehr großer Reichweite, die getroffene Monster betäubt. Die Miliz schlägt aus der Ferne zu, du auch.',
                      'Una alabarda de muy largo alcance que aturde a los monstruos golpeados. La Milicia golpea desde lejos, y tú también.',
                      'Un\'alabarda a lunghissima portata che stordisce i mostri colpiti. La Milizia colpisce da lontano, e anche tu.',
                      'Een hellebaard met heel groot bereik die geraakte monsters verdooft. De Militie slaat van ver, jij ook.',
                      'Uma alabarda de alcance muito longo que atordoa os monstros atingidos. A Milícia ataca de longe, e você também.')

